AssistantMessageToolRequest(name='create', tool_call_id='function-call-8be753e9-c03c-4ab2-bf30-826a160a75d3', arguments={'file_text': "const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  // Need to load the actual file so Babel script tags execute
  const fileUrl = 'file://' + path.resolve('index.html');
  await page.goto(fileUrl, { waitUntil: 'networkidle' });

  // Wait for React to render
  await page.waitForSelector('.support-form-container', { state: 'attached' });

  await page.addScriptTag({ path: '/tmp/axe.min.js' });

  const result = await page.evaluate(async () => {
    return await window.axe.run();
  });

  await browser.close();

  const wcag = result.violations.filter(v => !(v.tags || []).includes('best-practice'));
  const bp = result.violations.filter(v => (v.tags || []).includes('best-practice'));

  console.log(JSON.stringify({
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
    bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
  }, null, 2));

